-- A row generated by resetting the later fill keys to their FROM values must sort before the next original row.

SELECT '--- later key FROM above the data';
SELECT * FROM values('i Int64, j Int64, k Int64', (0, 0, 1), (1, 1, 2))
ORDER BY i WITH FILL, j WITH FILL FROM 2, k WITH FILL FROM 1;

SELECT '--- reset row placed after the original row, not duplicated';
SELECT * FROM values('i Int64, j Int64, k Int64', (0, 0, 1), (1, 1, 2), (1, 3, 0))
ORDER BY i WITH FILL, j WITH FILL FROM 2, k WITH FILL FROM 1;

SELECT '--- STALENESS';
SELECT * FROM values('i Int64, j Int64, k Int64', (0, 0, 1), (5, 1, 2))
ORDER BY i WITH FILL STALENESS 3, j WITH FILL FROM 2, k WITH FILL FROM 1;

SELECT '--- DESC';
SELECT * FROM values('i Int64, j Int64, k Int64', (0, 0, 1), (1, 1, 2))
ORDER BY i WITH FILL, j DESC WITH FILL FROM 0, k WITH FILL FROM 1;

SELECT '--- Nullable, reset row equal to the next original row';
SELECT * FROM values('i Int64, j Nullable(Int64)', (0, NULL), (1, NULL))
ORDER BY i WITH FILL, j WITH FILL;
